       prefix: '/',
       showHelpCommand: true
     }
   };
   ```

6. Enfin, créez un nouveau fichier nommé `commandHandler.ts` dans votre dossier racine, et y ajoutez :

   ```TypeScript
   import { Collection } from 'discord.js-commandhandler';

   export class DiscordCommandHandler {
     private commands = new Collection();
     private commandsCache = new Collection();

     register(command: DiscordCommand): this {
       this.commands.set(command.name, command);
       this.commandsCache.push(command.compile());
       return this;
     }

     static parseSlashCommand(command: string, interaction: SlashInteraction) {
       const commandData = this.commands.get(command);
       if (!commandData) {
         throw new Error(`Aucune commande trouvée`);
       }

       const command = commandData.run(interaction);
       if (command instanceof Promise) await command;

       return command;
     }
   }
   ```

   - Cette classe sera utilisée pour gérer les commandes slash du bot Discord.

7. Dans votre nouveau bot Discord, utilisez la commande `commandHandler.setSlashCommands()` :

   ```TypeScript
   import { Bot } from './Structures/Bot';

   Bot.on('ready').then(() => {
     Bot.application?.setSlashCommands();
   });
   ```

   - `Bot` est votre instance Discord.js du bot Discord
   - `Structures` et `commands` sont les dossiers contenant les fichiers respectifs

   Cette méthode envoie les requêtes de création de commandes slash au Discord, mais attend également les réponses des divers serveurs Discord où le bot est invité.

8. Dans votre fichier `BanCommand.ts`, modifiez la fonction `execute` pour correspondre à votre logique de bannissement :

   ```TypeScript
   export default class BanCommand {
   public static async execute(interaction: SlashInteraction) {
     // Votre logique de bannissement
   }
   }
   ```

   - Cette fonction sera appelée lorsque votre bot traitera une commande `bannir` envoyée dans un salon texte.

