                m_textures[blockIndex].height = m_blockSize;

                // Mettre à jour le prochain bloc à placer
                blockIndex += m_blockSize;

                // Augmenter la taille du serpent
                ++m_snakeLength;
            }
        } else if (event.type == SDL_MOUSEBUTTONUP) {
