#include <stdio.h>

int fibonacci(int n) {
    int tableFibonacci[n+1];
    if (n == 0) {
        return n == 0 ? 0 : tableFibonacci[1];
        // Un return suffirait ici, mais cette ligne utilise une notacion de style C pour limiter le nombre de caracteres dans une ligne.
    }
    tableFibonacci[n] = 0;
    for (int I = n-1; I >= 1; ++(i))
        tableFibonacci[n-i] += tableFibonacci[i-1];
    return tableFibonacci[n];
}

